// Route incoming MQTT messages
// output 1: Z-Wave JS UI client status or version / 2: API response (topic = api name)
// output 3: Z-Wave event (topic = source/event) / 4: value or node topic / 5: DKNR command

const mqtt = global.get('mqtt', 'default') || {};
const prefix = typeof mqtt.source === 'string' ? mqtt.source : '';
const topic = typeof mqtt.topic === 'string' ? mqtt.topic : '';
const t = typeof msg.topic === 'string' ? msg.topic : '';

// DKNR command: topic / set / zwave / id / entity
if (topic !== '' && t.startsWith(topic + '/set/zwave/')) {

    return [null, null, null, null, msg];
}

if (prefix === '' || !t.startsWith(prefix + '/')) {

    return;
}

const parts = t.slice(prefix.length + 1).split('/');

// write requests and API calls sent by anybody
if (parts[parts.length - 1] === 'set') {

    return;
}

// prefix / _CLIENTS / ZWAVE_GATEWAY-<name> / status | version | api / <name>
if (parts[0] === '_CLIENTS') {
    if (parts.length < 3) {

        return;
    }
    msg.client = parts[1];
    if (parts.length === 3 && (parts[2] === 'status' || parts[2] === 'version')) {
        msg.topic = parts[2];

        return [msg, null, null, null, null];
    }
    if (parts.length === 4 && parts[2] === 'api') {
        msg.topic = parts[3];

        return [null, msg, null, null, null];
    }

    // broadcast, multicast feedback
    return;
}

// prefix / _EVENTS / ZWAVE_GATEWAY-<name> / driver | node | controller / event_name
if (parts[0] === '_EVENTS') {
    if (parts.length !== 4) {

        return;
    }
    msg.client = parts[1];
    msg.topic = parts[2] + '/' + parts[3];

    return [null, null, msg, null, null];
}

msg.topic = parts.join('/');

return [null, null, null, msg, null];

// Z-Wave JS UI MQTT client status or version: prefix / _CLIENTS / ZWAVE_GATEWAY-<name> / status | version = {value, time}
// output 1: controller device updated / output 2: discovery / output 3: API requests / output 4: UI refresh

// Z-Wave JS UI API request: prefix / _CLIENTS / client / api / name / set = {args}
function api(name, args) {
    const mqtt = global.get('mqtt', 'default') || {};
    const client = global.get('client', 'memoryOnly') || {};
    if (typeof mqtt.source !== 'string' || mqtt.source === '' || typeof client.id !== 'string' || client.id === '') {

        return null;
    }

    return {
        'topic': [mqtt.source, '_CLIENTS', client.id, 'api', name, 'set'].join('/'),
        'payload': { 'args': args || [], 'dknr': Date.now() },
        'qos': 1,
        'retain': false
    };
}
// Z-Wave JS UI controller published as a DKNR device (id: controller), return true when created
function controller(devices, Z) {
    if (typeof devices.controller === 'object') {

        return false;
    }

    let entities = {};
    for (const k in Z.controller || {}) {
        const c = Z.controller[k];
        entities[k] = {
            'key': k,
            'name': c[0],
            'type': c[1],
            'access': c[2],
            'group': c[2] & 2 ? 'command' : 'sensor',
            'unit': '',
            'invert': false,
            'stateless': false,
            'value_on': true,
            'value_off': false,
            'ha_type': c[3],
            'ha_device': c[4],
            'ha_state': '',
            'ha_category': c[5],
            'ha_enabled': true
        };
    }

    devices.controller = {
        'id': 'controller',
        'nodeId': 0,
        'name': 'Z-Wave JS UI',
        'loc': '',
        'manufacturer': 'Z-Wave JS',
        'product': 'Z-Wave JS UI',
        'description': 'Passerelle Z-Wave JS UI',
        'firmware': '',
        'listening': true,
        'ready': true,
        'entities': entities,
        'values': {},
        'updated': Date.now()
    };

    return true;
}

let p = msg.payload;
if (Buffer.isBuffer(p)) {
    p = p.toString();
}
if (typeof p === 'string') {
    try {
        p = JSON.parse(p);
    } catch (e) {
        p = { 'value': p.trim() };
    }
}
if (typeof p !== 'object' || p === null) {
    p = { 'value': p };
}

const Z = ((global.get('describe', 'memoryOnly') || {}).zwave) || {};
const devices = global.get('devices', 'memoryOnly') || {};
let client = global.get('client', 'memoryOnly') || {};

const online = p.value === true || p.value === 'true';

// keep the current gateway while it is online
if (client.id !== msg.client) {
    if (typeof client.id === 'string' && client.state === true) {

        return;
    }
    client = { 'id': msg.client };
}

let requests = [];
if (msg.topic === 'status') {
    // gateway back online: read nodes and controller
    if (online && client.state !== true) {
        requests = [api('getNodes', []), api('getInfo', [])];
    }
    client.state = online;
} else {
    client.version = typeof p.value === 'string' ? p.value : String(p.value);
}

global.set('client', client, 'memoryOnly');

let added = controller(devices, Z);
const dev = devices.controller;
if (client.state !== undefined) {
    dev.values.state = client.state;
}
if (client.version !== undefined) {
    dev.values.version = client.version;
    if (dev.firmware !== client.version) {
        dev.firmware = client.version;
        added = true;
    }
}
dev.updated = Date.now();

global.set('devices', devices, 'memoryOnly');

node.status({ fill: client.state ? 'green' : 'red', shape: 'dot', text: client.id + (client.version ? ' ' + client.version : '') });

for (const r of requests) {
    if (r !== null) {
        node.send([null, null, r, null]);
    }
}

return [{ 'topic': 'controller', 'payload': 'controller' }, added ? { 'topic': 'discovery', 'payload': '' } : null, null, { 'payload': 'controller' }];

// Z-Wave JS UI API response: prefix / _CLIENTS / client / api / <name> = {success, message, result, origin}
// output 1: one message per device (topic = device id) / output 2: discovery
// output 3: MQTT (cleanup, new API requests) / output 4: notification / output 5: UI refresh

// Z-Wave JS UI API request: prefix / _CLIENTS / client / api / name / set = {args}
function api(name, args) {
    const mqtt = global.get('mqtt', 'default') || {};
    const client = global.get('client', 'memoryOnly') || {};
    if (typeof mqtt.source !== 'string' || mqtt.source === '' || typeof client.id !== 'string' || client.id === '') {

        return null;
    }

    return {
        'topic': [mqtt.source, '_CLIENTS', client.id, 'api', name, 'set'].join('/'),
        'payload': { 'args': args || [], 'dknr': Date.now() },
        'qos': 1,
        'retain': false
    };
}
// Z-Wave JS UI controller published as a DKNR device (id: controller), return true when created
function controller(devices, Z) {
    if (typeof devices.controller === 'object') {

        return false;
    }

    let entities = {};
    for (const k in Z.controller || {}) {
        const c = Z.controller[k];
        entities[k] = {
            'key': k,
            'name': c[0],
            'type': c[1],
            'access': c[2],
            'group': c[2] & 2 ? 'command' : 'sensor',
            'unit': '',
            'invert': false,
            'stateless': false,
            'value_on': true,
            'value_off': false,
            'ha_type': c[3],
            'ha_device': c[4],
            'ha_state': '',
            'ha_category': c[5],
            'ha_enabled': true
        };
    }

    devices.controller = {
        'id': 'controller',
        'nodeId': 0,
        'name': 'Z-Wave JS UI',
        'loc': '',
        'manufacturer': 'Z-Wave JS',
        'product': 'Z-Wave JS UI',
        'description': 'Passerelle Z-Wave JS UI',
        'firmware': '',
        'listening': true,
        'ready': true,
        'entities': entities,
        'values': {},
        'updated': Date.now()
    };

    return true;
}
// DKNR entity name of a Z-Wave value: commandClass _ endpoint _ property [_ propertyKey]
function key(v) {
    let k = [v.commandClass, v.endpoint || 0, v.property];
    if (v.propertyKey !== undefined && v.propertyKey !== null) {
        k.push(v.propertyKey);
    }

    return k.map(p => String(p).replace(/[^A-Za-z0-9]+/g, '_').replace(/^_+|_+$/g, '')).join('_');
}

let p = msg.payload;
if (Buffer.isBuffer(p)) {
    p = p.toString();
}
if (typeof p === 'string') {
    try {
        p = JSON.parse(p);
    } catch (e) {

        return;
    }
}
if (typeof p !== 'object' || p === null) {

    return;
}

let client = global.get('client', 'memoryOnly') || {};
if (typeof client.id !== 'string') {
    client = { 'id': msg.client, 'state': true };
    global.set('client', client, 'memoryOnly');
} else if (client.id !== msg.client) {

    return;
}

const Z = ((global.get('describe', 'memoryOnly') || {}).zwave) || {};
const mqtt = global.get('mqtt', 'default') || {};
const name = msg.topic;
const mine = typeof p.origin === 'object' && p.origin !== null && p.origin.dknr !== undefined;
const args = mine && Array.isArray(p.origin.args) ? p.origin.args : [];

if (p.success !== true) {
    node.status({ fill: 'red', shape: 'ring', text: name + ' : ' + (p.message || 'erreur') });

    return mine ? [null, null, null, { 'payload': 'Z-Wave JS UI : ' + name + ' : ' + (p.message || 'erreur') }, null] : null;
}

// ---------------------------------------------------------------- actions
const notices = {
    'startInclusion': 'Inclusion démarrée',
    'stopInclusion': 'Inclusion arrêtée',
    'startExclusion': 'Exclusion démarrée',
    'stopExclusion': 'Exclusion arrêtée',
    'setNodeName': 'Nœud renommé',
    'setNodeLocation': 'Emplacement modifié',
    'removeFailedNode': 'Nœud défaillant supprimé'
};

if (name !== 'getNodes' && name !== 'getInfo') {
    if (!mine || notices[name] === undefined) {

        return;
    }
    const next = ['setNodeName', 'setNodeLocation', 'removeFailedNode'].includes(name) ? api('getNodes', []) : api('getInfo', []);
    node.status({ fill: 'green', shape: 'dot', text: name + ' : ok' });

    return [null, null, next, { 'payload': notices[name] + (args.length > 1 && typeof args[1] === 'string' ? ' : ' + args[1] : '') }, null];
}

const devices = global.get('devices', 'memoryOnly') || {};
let added = controller(devices, Z);

// ---------------------------------------------------------------- controller
if (name === 'getInfo') {
    const r = typeof p.result === 'object' && p.result !== null ? p.result : {};
    const dev = devices.controller;
    client.info = {
        'homeid': r.homeid,
        'controllerId': r.controllerId,
        'appVersion': r.appVersion,
        'zwaveVersion': r.zwaveVersion,
        'status': r.status,
        'inclusionState': r.inclusionState
    };
    global.set('client', client, 'memoryOnly');

    dev.values.inclusion = r.inclusionState === 1;
    dev.values.exclusion = r.inclusionState === 2;
    if (typeof r.appVersion === 'string' && r.appVersion !== '') {
        dev.values.version = r.appVersion;
        if (dev.firmware !== r.appVersion) {
            dev.firmware = r.appVersion;
            added = true;
        }
    }
    dev.updated = Date.now();
    global.set('devices', devices, 'memoryOnly');

    node.status({ fill: 'green', shape: 'dot', text: 'contrôleur : ' + ((Z.inclusion || {})[String(r.inclusionState)] || '?') });

    return [{ 'topic': 'controller', 'payload': 'controller' }, added ? { 'topic': 'discovery', 'payload': '' } : null, null, null, { 'payload': 'controller' }];
}

// ---------------------------------------------------------------- nodes
if (!Array.isArray(p.result)) {

    return;
}

const types = ['boolean', 'number', 'string'];
const status = Z.status || {};
const statusFr = Z.status_fr || {};

function label(v) {
    // French name only for values without property key (Z-Wave JS labels of keyed values are more precise)
    const fr = v.propertyKey === undefined || v.propertyKey === null ? (Z.labels || {})[v.commandClass + '_' + (v.propertyName !== undefined ? v.propertyName : v.property)] : undefined;
    let l = fr || v.label || String(v.propertyName || v.property);
    if (v.endpoint > 0) {
        l += ' (canal ' + v.endpoint + ')';
    }

    return l;
}

function match(rules, text, unit) {
    for (const r of rules || []) {
        if (new RegExp(r[0], 'i').test(text) && (r.length < 3 || r[1] === unit)) {

