        ],
        'manufacturer': dev.manufacturer || 'Z-Wave',
        'model': [dev.product, dev.description].filter(v => v).join(' - ') || 'Z-Wave',
        'name': dev.name || id
    };
    if (typeof dev.loc === 'string' && dev.loc !== '') {
        device.suggested_area = dev.loc;
    }
    if (typeof dev.firmware === 'string' && dev.firmware !== '') {
        device.sw_version = dev.firmware;
    }
    if (id !== 'controller' && typeof devices.controller === 'object') {
        device.via_device = ['dknr', source, 'controller'].join('_');
    }

    for (const k in dev.entities) {
        const def = dev.entities[k];

        // dknr
        let options = {};
        if (def.type === 'enum') {
            for (const v of def.values || []) {
                options[v] = v;
            }
        }
        node.send({
            'topic': [topic, 'discovery', source, id, k].join('/'),
            'payload': {
                'name': def.name,
                'group': def.group,
                'type': def.type,
                'unit': def.unit,
                'value': defaults[def.type],
                'options': options
            },
            'qos': 0,
            'retain': true
        });

        // ha
        if (discovery === '') {

            continue;
        }

        let payload = {
            'unique_id': ['dknr', source, id, k].join('_'),
            'name': def.name,
            'state_topic': [topic, 'get', source, id, k].join('/'),
            'device': device
        };

        if (def.ha_category !== '') {
            payload.entity_category = def.ha_category;
        }
        if (def.ha_enabled === false) {
            payload.enabled_by_default = false;
        }

        // dead node: entities unavailable
        if (k !== 'status' && typeof dev.entities.status === 'object') {
            payload.availability_topic = [topic, 'get', source, id, 'status'].join('/');
            payload.availability_template = "{{ 'offline' if value == 'Mort' else 'online' }}";
            payload.payload_available = 'online';
            payload.payload_not_available = 'offline';
        }

        if (def.ha_type === 'sensor') {
            if (def.unit !== '') {
                payload.unit_of_measurement = def.unit;
            }
            if (def.ha_state !== '') {
                payload.state_class = def.ha_state;
            }
            if (def.ha_device !== '') {
                payload.device_class = def.ha_device;
            }
            if (def.ha_device === 'enum') {
                payload.options = def.values;
            }
        }
        else if (def.ha_type === 'binary_sensor') {
            payload.payload_on = def.invert ? 'OFF' : 'ON';
            payload.payload_off = def.invert ? 'ON' : 'OFF';
            if (def.ha_device !== '') {
                payload.device_class = def.ha_device;
            }
        }
        else if (def.ha_type === 'switch') {
            payload.command_topic = [topic, 'set', source, id, k].join('/');
            payload.payload_on = 'ON';
            payload.payload_off = 'OFF';
            payload.state_on = 'ON';
            payload.state_off = 'OFF';
        }
        else if (def.ha_type === 'number') {
            payload.command_topic = [topic, 'set', source, id, k].join('/');
            payload.min = typeof def.min === 'number' ? def.min : -1000000;
            payload.max = typeof def.max === 'number' ? def.max : 1000000;
            payload.step = typeof def.step === 'number' ? def.step : 1;
            payload.mode = typeof def.min === 'number' && typeof def.max === 'number' ? 'auto' : 'box';
            if (def.unit !== '') {
                payload.unit_of_measurement = def.unit;
            }
        }
        else if (def.ha_type === 'select' && Array.isArray(def.values) && def.values.length > 0) {
            payload.command_topic = [topic, 'set', source, id, k].join('/');
            payload.options = def.values;
        }
        else if (def.ha_type === 'text') {
            payload.command_topic = [topic, 'set', source, id, k].join('/');
        }
        else if (def.ha_type === 'button') {
            delete payload.state_topic;
            payload.command_topic = [topic, 'set', source, id, k].join('/');
            payload.payload_press = 'ON';
        }
        else {

            continue;
        }

        node.send({
            'topic': [discovery, def.ha_type, source, id + '_' + k, 'config'].join('/'),
            'payload': payload,
            'qos': 0,
            'retain': true
        });
    }
}

return;

// Fill device selector
// output 1: auto select single device / output 2: dropdown

flow.set('current_device', '', 'memoryOnly');
flow.set('current_entity', '', 'memoryOnly');

delete msg.dashboard;
delete msg.tab;
delete msg.name;
delete msg.version;
delete msg.title;
delete msg.full;
delete msg.git;
delete msg.lang;
delete msg.menus;
delete msg.titles;
delete msg.options;

const devices = global.get('devices', 'memoryOnly') || {};
const ids = Object.keys(devices)
    .filter(id => Object.keys(devices[id].entities || {}).length > 0)
    .sort((a, b) => (a === 'controller' ? -1 : (b === 'controller' ? 1 : devices[a].nodeId - devices[b].nodeId)));

msg.payload = '';
msg.class = '';
msg.enabled = true;
msg.options = [{
    'label': '',
    'value': ''
}];

for (const id of ids) {
    msg.options.push({
        'label': (id === 'controller' ? '' : id + ' - ') + devices[id].name + (devices[id].product ? ' (' + devices[id].product + ')' : ''),
        'value': id
    });
}

if (ids.length === 0) {
    msg.class = 'remove';
    msg.enabled = false;
    msg.options = [];

    return [null, msg];
}

if (ids.length === 1) {
    node.send([{ 'payload': ids[0] }, null]);
    msg.class = 'remove';
    msg.enabled = false;

    return [null, msg];
}

return [null, msg];

// Show a device
// output 1: table / output 2: command selector / output 3: value selector / output 4: value form
// output 5: read button / output 6: refresh loop
// msg.refresh: only refresh the table

const devices = global.get('devices', 'memoryOnly') || {};
const id = msg.payload;
const dev = devices[id];
const refresh = msg.refresh === true;

const hide = { 'payload': '', 'class': 'remove', 'enabled': false };

if (typeof dev !== 'object') {
    flow.set('current_device', '', 'memoryOnly');
    flow.set('current_entity', '', 'memoryOnly');

    return [{ 'payload': [], 'class': 'remove' }, refresh ? null : { ...hide, 'options': [] }, refresh ? null : hide, refresh ? null : { 'class': 'remove' }, refresh ? null : hide, null];
}

if (refresh && flow.get('current_device', 'memoryOnly') !== id) {

    return;
}

flow.set('current_device', id, 'memoryOnly');

function display(def, raw) {
    if (raw === undefined || raw === null || raw === '') {

        return undefined;
    }
    switch (def.type) {
        case 'binary': {
            const on = raw === def.value_on;
            if (raw !== def.value_on && raw !== def.value_off) {

                return String(raw);
            }
            if (id === 'controller' && def.key === 'state') {

                return on ? 'En ligne' : 'Hors ligne';
            }
            if (def.display === 'state') {

                return on ? 'Allumé' : 'Eteint';
            }
            if (def.display === 'contact') {

                return on ? 'Ouvert' : 'Fermé';
            }

            return on ? 'Oui' : 'Non';
        }
        case 'number':

            return String(raw) + (def.unit ? ' ' + def.unit : '');
        case 'enum':
            if (Array.isArray(def.states)) {
                const s = def.states.find(s => s.value === raw || String(s.value) === String(raw));
                if (s) {

                    return s.text;
                }
            }

            return String(raw);
        default:
            if (def.ha_device === 'timestamp') {
                const d = new Date(raw);
                if (!isNaN(d.getTime())) {

                    return d.toLocaleString('fr-FR', { 'timeZone': env.get('TZ') || 'Europe/Paris' });
                }
            }

            return typeof raw === 'object' ? JSON.stringify(raw) : String(raw);
    }
}

let rows = [];
function add(lbl, val) {
    if (val !== undefined && val !== null && val !== '') {
        rows.push({ 'lbl': lbl, 'val': String(val) });
    }
}

add('Nom', dev.name);
add('Emplacement', dev.loc);
add('Fabricant', dev.manufacturer);
add('Modèle', dev.product);
add('Description', dev.description);
if (id !== 'controller') {
    add('Nœud', dev.nodeId);
    add('Ecoute', dev.listening ? 'Permanente (secteur)' : 'Au réveil (pile)');
}

const keys = Object.keys(dev.entities).sort((a, b) => String(dev.entities[a].name).localeCompare(String(dev.entities[b].name)));
for (const k of keys) {
    add(dev.entities[k].name, display(dev.entities[k], dev.values[k]));
}

add('Firmware', dev.firmware);

if (refresh) {

    return [{ 'payload': rows, 'class': '' }, null, null, null, null, { 'payload': id }];
}

// command selector
flow.set('current_entity', '', 'memoryOnly');

let options = [{ 'label': '', 'value': '' }];
for (const k of keys) {
    if (dev.entities[k].access & 2) {
        options.push({ 'label': dev.entities[k].name, 'value': k });
    }
}
const commands = options.length > 1
    ? { 'payload': '', 'options': options, 'class': '', 'enabled': true }
    : { 'payload': '', 'options': [], 'class': 'remove', 'enabled': false };

// read button, only for devices answering to get requests
const readable = id !== 'controller';

return [
    { 'payload': rows, 'class': '' },
    commands,
    hide,
    { 'class': 'remove' },
    readable ? { 'payload': '', 'class': '', 'enabled': true } : hide,
    { 'payload': id }
];

// Command selected: show value selector (binary, enum) or value form (number, text)
// output 1: value selector / output 2: value form

const devices = global.get('devices', 'memoryOnly') || {};
const id = flow.get('current_device', 'memoryOnly') || '';
const dev = devices[id];
const k = typeof msg.payload === 'string' ? msg.payload : '';

const hide = { 'payload': '', 'options': [], 'class': 'remove', 'enabled': false };

if (typeof dev !== 'object' || k === '' || typeof dev.entities[k] !== 'object') {
    flow.set('current_entity', '', 'memoryOnly');

    return [hide, { 'class': 'remove' }];
}

flow.set('current_entity', k, 'memoryOnly');

const def = dev.entities[k];

if (def.type === 'binary' && def.ha_type === 'button') {

    return [{
        'payload': '',
        'class': '',
        'enabled': true,
        'options': [{ 'label': '', 'value': '' }, { 'label': 'Déclencher', 'value': 'ON' }]
    }, { 'class': 'remove' }];
}

if (def.type === 'binary') {
    const state = def.display === 'state';

    return [{
        'payload': '',
        'class': '',
        'enabled': true,
        'options': [
            { 'label': '', 'value': '' },
            { 'label': state ? 'Allumer' : 'Activer', 'value': 'ON' },
            { 'label': state ? 'Eteindre' : 'Désactiver', 'value': 'OFF' },
            { 'label': 'Inverser', 'value': 'TOGGLE' }
        ]
    }, { 'class': 'remove' }];
}

if (def.type === 'enum') {

    return [{
        'payload': '',
        'class': '',
        'enabled': true,
        'options': [{ 'label': '', 'value': '' }].concat((def.values || []).map(v => ({ 'label': v, 'value': v })))
    }, { 'class': 'remove' }];
}

// number or text: prefill the form with the current value
let value = dev.values[k];
if (value === undefined || value === null || typeof value === 'object') {
    value = '';
}

return [hide, { 'payload': { 'value': String(value) }, 'class': '' }];

// UI value to pilot
// input: value selector (payload = value) or value form (payload = {value})
// output 1: pilot / output 2: reset value selector

const id = flow.get('current_device', 'memoryOnly') || '';
const k = flow.get('current_entity', 'memoryOnly') || '';

let value = msg.payload;
if (typeof value === 'object' && value !== null) {
    value = value.value;
}

if (id === '' || k === '' || value === undefined || value === null || value === '') {

    return;
}

return [{
    'topic': id,
    'payload': {
        'id': id,
        'property': k,
        'value': value
    }
}, typeof msg.payload === 'object' ? null : { 'payload': '' }];

// Ask Z-Wave JS UI to read all the values of the current node again
// output 1: Z-Wave JS UI API request / output 2: notification

// Z-Wave JS UI API request: prefix / _CLIENTS / client / api / name / set = {args}
function api(name, args) {
    const mqtt = global.get('mqtt', 'default') || {};
    const client = global.get('client', 'memoryOnly') || {};
    if (typeof mqtt.source !== 'string' || mqtt.source === '' || typeof client.id !== 'string' || client.id === '') {

        return null;
    }

    return {
        'topic': [mqtt.source, '_CLIENTS', client.id, 'api', name, 'set'].join('/'),
        'payload': { 'args': args || [], 'dknr': Date.now() },
        'qos': 1,
        'retain': false
    };
}

const devices = global.get('devices', 'memoryOnly') || {};
const id = flow.get('current_device', 'memoryOnly') || '';
const dev = devices[id];

if (typeof dev !== 'object' || id === 'controller') {

    return;
}

const request = api('refreshValues', [dev.nodeId]);
if (request === null) {

    return [null, { 'payload': 'Passerelle Z-Wave JS UI inconnue' }];
}

return [request, { 'payload': dev.listening ? 'Lecture de ' + dev.name + ' demandée' : dev.name + ' sera relu à son prochain réveil' }];

// Z-Wave network page
// output 1: controller table / output 2: nodes table / output 3: node selector (page opened or nodes list changed)

const Z = ((global.get('describe', 'memoryOnly') || {}).zwave) || {};
const client = global.get('client', 'memoryOnly') || {};
const devices = global.get('devices', 'memoryOnly') || {};
const info = client.info || {};
const tz = env.get('TZ') || 'Europe/Paris';

function date(v) {
    const d = new Date(v);
    if (v === undefined || v === null || v === '' || isNaN(d.getTime())) {

        return '';
    }

    return d.toLocaleString('fr-FR', { 'timeZone': tz });
}

const ids = Object.keys(devices)
    .filter(id => id !== 'controller')
    .sort((a, b) => devices[a].nodeId - devices[b].nodeId);

// controller
let rows = [];
function add(lbl, val) {
    if (val !== undefined && val !== null && val !== '') {
        rows.push({ 'lbl': lbl, 'val': String(val) });
    }
}

const c = (devices.controller || {}).values || {};
add('Passerelle', client.state === undefined ? 'Inconnue' : (client.state ? 'En ligne' : 'Hors ligne') + (client.id ? ' (' + client.id + ')' : ''));
add('Version', c.version);
add('Z-Wave JS', info.zwaveVersion);
add('Home ID', typeof info.homeid === 'number' ? '0x' + info.homeid.toString(16).padStart(8, '0') : '');
add('Contrôleur', info.controllerId || client.controllerId);
add('Etat', c.inclusion ? 'Inclusion en cours' : (c.exclusion ? 'Exclusion en cours' : (Z.inclusion || {})[String(info.inclusionState)]));
add('Nœuds', ids.length);

// nodes
let list = [];
for (const id of ids) {
    const d = devices[id];
    const v = d.values || {};
    let battery = '';
    const b = Object.keys(d.entities || {}).find(k => k.startsWith('128_') && d.entities[k].type === 'number');
    if (b !== undefined && typeof v[b] === 'number') {
        battery = v[b] + ' %';
    }

    list.push({
        'id': d.nodeId,
        'name': d.name,
        'loc': d.loc,
        'model': [d.manufacturer, d.product].filter(x => x).join(' '),
        'battery': battery,
        'seen': date(v.lastActive),
        'state': d.failed ? 'Défaillant' : (d.ready ? (v.status || '') : 'Interrogation en cours')
    });
}

let select = null;
if (msg.payload !== 'controller' && msg.payload !== 'status') {
    flow.set('current_manage', '', 'memoryOnly');
    select = {
        'payload': '',
        'class': ids.length > 0 ? '' : 'remove',
        'enabled': ids.length > 0,
        'options': [{ 'label': '', 'value': '' }].concat(ids.map(id => ({ 'label': id + ' - ' + devices[id].name + (devices[id].product ? ' (' + devices[id].product + ')' : ''), 'value': id })))
    };
}

return [
    { 'payload': rows },
    { 'payload': list, 'class': list.length > 0 ? '' : 'remove' },
    select
];

// Inclusion buttons: INCLUDE / EXCLUDE / STOP

const devices = global.get('devices', 'memoryOnly') || {};
const c = (devices.controller || {}).values || {};

function order(property, value) {

    return { 'topic': 'controller', 'payload': { 'id': 'controller', 'property': property, 'value': value } };
}

switch (msg.payload) {
    case 'INCLUDE':

        return order('inclusion', 'ON');
    case 'EXCLUDE':

        return order('exclusion', 'ON');
    case 'STOP':

        return c.exclusion === true ? order('exclusion', 'OFF') : order('inclusion', 'OFF');
}

return;

// Select a node to rename, move or remove, prefill the form

const devices = global.get('devices', 'memoryOnly') || {};
const id = typeof msg.payload === 'string' ? msg.payload : '';

if (id === '' || id === 'controller' || typeof devices[id] !== 'object') {
    flow.set('current_manage', '', 'memoryOnly');

    return { 'payload': { 'name': '', 'loc': '', 'remove': false }, 'class': 'remove' };
}

flow.set('current_manage', id, 'memoryOnly');

return { 'payload': { 'name': devices[id].name, 'loc': devices[id].loc || '', 'remove': false }, 'class': '' };

// Rename, move or remove the selected node through Z-Wave JS UI
// output 1: Z-Wave JS UI API requests / output 2: notification

// Z-Wave JS UI API request: prefix / _CLIENTS / client / api / name / set = {args}
function api(name, args) {
    const mqtt = global.get('mqtt', 'default') || {};
    const client = global.get('client', 'memoryOnly') || {};
    if (typeof mqtt.source !== 'string' || mqtt.source === '' || typeof client.id !== 'string' || client.id === '') {

        return null;
    }

    return {
        'topic': [mqtt.source, '_CLIENTS', client.id, 'api', name, 'set'].join('/'),
        'payload': { 'args': args || [], 'dknr': Date.now() },
        'qos': 1,
        'retain': false
    };
}

const devices = global.get('devices', 'memoryOnly') || {};
const id = flow.get('current_manage', 'memoryOnly') || '';
const dev = devices[id];
const p = msg.payload || {};

if (typeof dev !== 'object') {

    return [null, { 'payload': 'Sélectionnez un nœud' }];
}

if (api('getNodes', []) === null) {

    return [null, { 'payload': 'Passerelle Z-Wave JS UI inconnue' }];
}

// remove a failed node (Z-Wave JS refuses to remove a node that still answers)
if (p.remove === true) {
    flow.set('current_manage', '', 'memoryOnly');

    return [api('removeFailedNode', [dev.nodeId]), { 'payload': 'Suppression du nœud ' + id + ' demandée' }];
}

const name = String(p.name || '').trim();
const loc = String(p.loc || '').trim();
let requests = [];

if (name !== '' && name !== dev.name) {
    requests.push(api('setNodeName', [dev.nodeId, name]));
}
if (loc !== (dev.loc || '')) {
    requests.push(api('setNodeLocation', [dev.nodeId, loc]));
}

if (requests.length === 0) {

    return [null, { 'payload': 'Aucune modification' }];
}

for (const r of requests) {
    node.send([r, null]);
}

return;
